import { useState, KeyboardEvent, ChangeEvent } from 'react';
import { Input, Tag, Stack } from '@jinx-ui/react';

interface TagInputProps {
  onChange?: (tags: string[]) => void;
  placeholder?: string;
}

export default function TagInput({ onChange, placeholder = 'Введите тег и нажмите Enter' }: TagInputProps) {
  const [tags, setTags] = useState<string[]>([]);
  const [inputValue, setInputValue] = useState('');

  const updateTags = (newTags: string[]) => {
    setTags(newTags);
    onChange?.(newTags);
  };

  const addTag = (rawValue: string) => {
    const value = rawValue.trim();
    if (!value) return;
    if (tags.includes(value)) {
      setInputValue('');
      return;
    }
    updateTags([...tags, value]);
    setInputValue('');
  };

  const removeTag = (tagToRemove: string) => {
    updateTags(tags.filter((tag) => tag !== tagToRemove));
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag(inputValue);
    } else if (event.key === 'Backspace' && inputValue === '' && tags.length > 0) {
      updateTags(tags.slice(0, -1));
    }
  };

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    setInputValue(event.target.value);
  };

  const handleBlur = () => {
    if (inputValue.trim()) {
      addTag(inputValue);
    }
  };

  return (
    <Stack direction="column" gap="var(--jx-space-2)">
      <Input
        value={inputValue}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        onBlur={handleBlur}
        placeholder={placeholder}
        aria-label="Добавить тег"
      />
      {tags.length > 0 && (
        <Stack direction="row" gap="var(--jx-space-1)" wrap="wrap">
          {tags.map((tag) => (
            <Tag key={tag} onRemove={() => removeTag(tag)} removable>
              {tag}
            </Tag>
          ))}
        </Stack>
      )}
    </Stack>
  );
}

